VRT_L("tle-a-maths-r01",{"duree":20,"titre":"Équations et inéquations de degré 3","accroche":"Trois facteurs, et le problème se résout.","intro":"Une équation de degré 3 se résout en la factorisant à l'aide d'une racine évidente.","objectifs":["trouver une racine évidente","factoriser","étudier un signe"],"parties":[{"t":"Racine et factorisation","html":"<div class='def'><b>Définition</b>Une <strong>équation de degré 3</strong> s'écrit ax³ + bx² + cx + d = 0. Si r en est une racine, le polynôme se factorise par (x − r).</div>"},{"t":"Exemple","html":"<p>x³ − 6x² + 11x − 6 = (x − 1)(x − 2)(x − 3). Les solutions sont 1, 2 et 3.</p>","labo":{"type":"trier","invite":"Choisis une valeur.","items":[["x = 1","racine : le produit s'annule."],["x = 2","racine : le produit s'annule."],["x = 3","racine : le produit s'annule."]]}},{"t":"Inéquation","html":"<p>On dresse un tableau de signes. Ici, le produit est positif sur ]1 ; 2[ ∪ ]3 ; +∞[.</p>","retenir":"Chercher une racine parmi 1, −1, 2, −2."},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Question de cours.</strong> Si 2 est racine, on factorise par :</p><ol type='a'><li>x + 2</li><li>x − 2</li><li>2x</li></ol><details><summary>Voir la réponse</summary><p><strong>x − 2</strong>. (x − r).</p></details><p><strong>Exercice.</strong></p><p>Résous x³ − x = 0.</p><details><summary>Voir la réponse</summary><p>(Réponse : −1 ; 0 ; 1.)</p></details><h3>Partie B : évaluation des compétences</h3><p><strong>Situation.</strong> Le bénéfice d'un groupement d'éleveurs de Ngaoundéré est modélisé par B(x) = x³ − 2x² − 5x + 6, en centaines de milliers de francs, où x est le nombre de centaines de poulets vendus (0 ≤ x ≤ 5).</p><p><strong>Tâche 1.</strong> Vérifie que 1 est racine de B(x), puis factorise B(x).</p><p><strong>Tâche 2.</strong> Pour quelles ventes le groupement ne perd-il pas d'argent ?</p><details><summary>Voir une réponse attendue</summary><p>B(1) = 1 − 2 − 5 + 6 = 0. B(x) = (x − 1)(x² − x − 6) = (x − 1)(x − 3)(x + 2). Sur [0 ; 5], x + 2 > 0 ; B(x) ≥ 0 quand (x − 1)(x − 3) ≥ 0, soit x ∈ [0 ; 1] ∪ [3 ; 5] : moins de 100 poulets ou de 300 à 500 poulets.</p></details></div>","retenir":"Savoir-être mobilisé : Rigueur dans la rédaction."}],"revision":["Racine évidente.","Factoriser.","Tableau de signes."],"exo":"<p>Résous x³ − x = 0. <em>(Réponse : −1 ; 0 ; 1.)</em></p>","quiz":[{"q":"Si 2 est racine, on factorise par :","r":["x + 2","x − 2","2x"],"b":1,"e":"(x − r)."},{"q":"x³ − x vaut :","r":["x(x − 1)(x + 1)","x(x − 1)²","x³"],"b":0,"e":"Factorisation."},{"q":"Pour l'inéquation, on utilise :","r":["un cercle","le PGCD","un tableau de signes"],"b":2,"e":"Pour conclure."},{"q":"(x − 1)(x − 2) = 0 a pour solutions :","r":["−1 et −2","1 et 2","0"],"b":1,"e":"Produit nul."}],"c":"Tle A","m":"maths","rang":1,"apc":{"module":"Mathématiques de Terminale A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations et interpréter des résultats","situation":"Une commerçante de Bafoussam modélise son bénéfice par (x − 1)(x − 2)(x − 3), où x représente des centaines d'articles.","tache":"Trouve pour quelles quantités le bénéfice est nul."},"gratuit":true});
VRT_L("tle-a-maths-r02",{"duree":20,"titre":"Équations avec inconnue auxiliaire","accroche":"Remplacer x² par X, et l'équation se simplifie.","intro":"Certaines équations difficiles se ramènent à une équation du second degré.","objectifs":["poser une inconnue auxiliaire","résoudre","revenir à l'inconnue"],"parties":[{"t":"Principe","html":"<div class='def'><b>Méthode</b>Une <strong>inconnue auxiliaire</strong> X remplace une expression, comme x², pour obtenir une équation plus simple.</div>"},{"t":"Exemple","verrou":true},{"t":"Attention","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle A","m":"maths","rang":2,"apc":{"module":"Mathématiques de Terminale A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations et interpréter des résultats","situation":"Un éleveur de Maroua veut deux enclos carrés de côté x mètres ; l'aire x² vérifie x⁴ − 5x² + 4 = 0, condition imposée par le grillage disponible.","tache":"Trouve les côtés positifs possibles."},"verrou":true,"nq":4,"labo":true});
VRT_L("tle-a-maths-r03",{"duree":20,"titre":"Systèmes linéaires dans ℝ²","accroche":"Deux équations pour trouver deux prix.","intro":"Les systèmes traduisent de nombreuses situations commerciales.","objectifs":["résoudre par substitution","résoudre par combinaison","interpréter"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Un <strong>système linéaire</strong> de deux équations à deux inconnues se résout en éliminant une inconnue.</div>"},{"t":"Exemple","verrou":true},{"t":"Interpréter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle A","m":"maths","rang":3,"apc":{"module":"Mathématiques de Terminale A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations et interpréter des résultats","situation":"Au marché de Mokolo, 2 kg de haricots et 1 kg de riz coûtent 7 000 F ; 1 kg de haricots coûte 2 000 F de plus que 1 kg de riz.","tache":"Trouve les prix au kilogramme."},"verrou":true,"nq":4,"labo":true});
VRT_L("tle-a-maths-r04",{"duree":25,"titre":"Systèmes linéaires dans ℝ³","accroche":"Trois inconnues, résolues en escalier.","intro":"La méthode du pivot de Gauss transforme un système en triangle.","objectifs":["triangulariser","résoudre de bas en haut","vérifier"],"parties":[{"t":"Pivot de Gauss","html":"<div class='def'><b>Méthode</b>Le <strong>pivot de Gauss</strong> élimine progressivement les inconnues pour obtenir un système triangulaire.</div>"},{"t":"Exemple","verrou":true},{"t":"Vérifier","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle A","m":"maths","rang":4,"apc":{"module":"Mathématiques de Terminale A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations et interpréter des résultats","situation":"Un groupe d'artisans de Foumban vend trois articles. Le total des trois prix vaut 6 000 F, les deux derniers valent 5 000 F, le dernier 3 000 F.","tache":"Trouve chaque prix."},"verrou":true,"nq":4,"labo":true});
VRT_L("tle-a-maths-r05",{"duree":25,"titre":"Intégration : le budget d'une coopérative","accroche":"Trouver trois prix avec trois informations.","intro":"Une coopérative doit retrouver les prix unitaires à partir de ses factures.","objectifs":["traduire un problème","résoudre un système","conclure"],"parties":[{"t":"Traduire","html":"<div class='def'><b>Activité d'intégration</b>Elle consiste à <strong>mettre en équation</strong> une situation concrète, puis à résoudre le système obtenu.</div><p>a + b + c = 900 ; a + b = 700 ; b + c = 500.</p>"},{"t":"Résoudre","verrou":true},{"t":"Conclure","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle A","m":"maths","rang":5,"apc":{"module":"Mathématiques de Terminale A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations et interpréter des résultats","situation":"Une coopérative de Dschang a payé trois produits 900 F au total, les deux premiers 700 F, les deux derniers 500 F.","tache":"Détermine le prix de chaque produit."},"verrou":true,"nq":4,"labo":true});
VRT_L("tle-a-maths-r06",{"duree":20,"titre":"Limite d'une fonction en l'infini","accroche":"Que devient une grandeur quand x devient immense ?","intro":"La limite décrit le comportement d'une fonction pour de très grandes valeurs.","objectifs":["calculer une limite en ±∞","utiliser les termes de plus haut degré","interpréter"],"parties":[{"t":"Définition","html":"<div class='def'><b>Notion</b>La <strong>limite en +∞</strong> indique la valeur vers laquelle se rapproche f(x), ou son comportement, quand x devient très grand.</div>"},{"t":"Règle","verrou":true},{"t":"Interpréter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle A","m":"maths","rang":6,"apc":{"module":"Mathématiques de Terminale A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations et interpréter des résultats","situation":"Le coût moyen d'un livre imprimé à Yaoundé vaut (500x + 10 000) / x, x étant le nombre d'exemplaires.","tache":"Dis vers quelle valeur tend ce coût moyen."},"verrou":true,"nq":4,"labo":true});
VRT_L("tle-a-maths-r07",{"duree":15,"titre":"Limite d'une fonction en un réel","accroche":"S'approcher d'un point, sans forcément l'atteindre.","intro":"Une fonction peut avoir une limite en un réel même si elle n'y est pas définie.","objectifs":["calculer une limite en un réel","simplifier une fraction","lever 0/0"],"parties":[{"t":"Le cas simple","html":"<div class='def'><b>Propriété</b>Pour les fonctions usuelles, si f est définie en a, alors <strong>lim (x→a) f(x) = f(a)</strong>.</div>"},{"t":"Forme 0/0","verrou":true},{"t":"Méthode","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle A","m":"maths","rang":7,"apc":{"module":"Mathématiques de Terminale A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations et interpréter des résultats","situation":"Un tableau de bord de vente de Douala calcule une variation par (x² − 1)/(x − 1) et affiche une erreur en x = 1.","tache":"Donne la valeur limite."},"verrou":true,"nq":4,"labo":true});
VRT_L("tle-a-maths-r08",{"duree":15,"titre":"Limite à gauche et à droite","accroche":"Arriver d'un côté ou de l'autre change parfois tout.","intro":"Une limite peut différer selon le côté par lequel on s'approche.","objectifs":["calculer une limite à gauche","calculer une limite à droite","comparer"],"parties":[{"t":"Définition","html":"<div class='def'><b>Notation</b>x → a⁺ : x s'approche de a par la <strong>droite</strong>. x → a⁻ : par la <strong>gauche</strong>.</div>"},{"t":"Exemple","verrou":true},{"t":"Conclusion","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle A","m":"maths","rang":8,"apc":{"module":"Mathématiques de Terminale A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations et interpréter des résultats","situation":"Une prime à Bertoua change brutalement au seuil de 1 000 ventes.","tache":"Explique ce qu'apporte l'étude à gauche et à droite du seuil."},"verrou":true,"nq":4,"labo":true});
VRT_L("tle-a-maths-r09",{"duree":15,"titre":"Limites et opérations","accroche":"Certaines opérations n'ont pas de réponse immédiate.","intro":"On peut additionner, multiplier ou diviser des limites, sauf dans certains cas.","objectifs":["appliquer les règles","repérer une forme indéterminée","transformer l'expression"],"parties":[{"t":"Règles","html":"<div class='def'><b>Règle</b>La limite d'une somme, d'un produit ou d'un quotient se déduit des limites, sauf pour les <strong>formes indéterminées</strong>.</div>"},{"t":"Formes indéterminées","verrou":true},{"t":"Exemple","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle A","m":"maths","rang":9,"apc":{"module":"Mathématiques de Terminale A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations et interpréter des résultats","situation":"En comparant recettes et dépenses à long terme d'un commerce de Kumba, on trouve x² − x.","tache":"Dis si le bénéfice devient très grand."},"verrou":true,"nq":4,"labo":true});
VRT_L("tle-a-maths-r10",{"duree":15,"titre":"La continuité","accroche":"Pas de saut sur la courbe.","intro":"Une fonction continue se trace sans lever le crayon.","objectifs":["définir la continuité","reconnaître une fonction continue","étudier un raccord"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>f est <strong>continue en a</strong> si lim (x→a) f(x) = f(a).</div>"},{"t":"Fonctions continues","verrou":true},{"t":"Raccord","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle A","m":"maths","rang":10,"apc":{"module":"Mathématiques de Terminale A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations et interpréter des résultats","situation":"Un tarif de transport à Bafia change à partir de 10 km.","tache":"Dis comment vérifier qu'il n'y a pas de saut de prix."},"verrou":true,"nq":4,"labo":true});
VRT_L("tle-a-maths-r11",{"duree":15,"titre":"Représentations graphiques d'une série","accroche":"Choisir le bon graphique, c'est déjà convaincre.","intro":"Une série statistique peut se représenter de plusieurs façons selon l'information à montrer.","objectifs":["choisir un graphique","construire un diagramme","lire un histogramme"],"parties":[{"t":"Les types","html":"<div class='def'><b>Définition</b>Une <strong>représentation graphique</strong> traduit visuellement une série : bâtons, circulaire, histogramme.</div>"},{"t":"Choisir","verrou":true},{"t":"Lire","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle A","m":"maths","rang":11,"apc":{"module":"Mathématiques de Terminale A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations et interpréter des résultats","situation":"Un candidat au conseil municipal de Bafang présente les dépenses de sa commune.","tache":"Dis quel graphique montre le mieux la part de chaque poste."},"verrou":true,"nq":4,"labo":true});
VRT_L("tle-a-maths-r12",{"duree":20,"titre":"Mode, médiane, moyenne, quartiles et déciles","accroche":"Une moyenne peut mentir, la médiane beaucoup moins.","intro":"Plusieurs indicateurs résument une série de données de manières différentes.","objectifs":["calculer les indicateurs","interpréter","comparer moyenne et médiane"],"parties":[{"t":"Définitions","html":"<div class='def'><b>Définitions</b>Le <strong>mode</strong> est la valeur la plus fréquente. La <strong>médiane</strong> partage la série en deux moitiés. Les <strong>quartiles</strong> la partagent en quatre.</div>"},{"t":"Exemple","verrou":true},{"t":"Interpréter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle A","m":"maths","rang":12,"apc":{"module":"Mathématiques de Terminale A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations et interpréter des résultats","situation":"Dans une entreprise de Douala, 9 salariés touchent peu et le directeur beaucoup.","tache":"Dis quel indicateur représente le mieux le salaire courant."},"verrou":true,"nq":4,"labo":true});
VRT_L("tle-a-maths-r13",{"duree":15,"titre":"Série statistique à deux caractères","accroche":"Le prix et les ventes évoluent-ils ensemble ?","intro":"Une série double étudie deux caractères sur les mêmes individus.","objectifs":["construire un nuage de points","calculer le point moyen","lire la tendance"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Une <strong>série double</strong> associe deux valeurs à chaque individu. Elle se représente par un <strong>nuage de points</strong>.</div>"},{"t":"Point moyen","verrou":true},{"t":"Tendance","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle A","m":"maths","rang":13,"apc":{"module":"Mathématiques de Terminale A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations et interpréter des résultats","situation":"Une vendeuse de pagnes de Garoua note ses prix et ses ventes sur cinq semaines.","tache":"Dis quel outil permet de voir s'il existe un lien."},"verrou":true,"nq":4,"labo":true});
VRT_L("tle-a-maths-r14",{"duree":20,"titre":"L'ajustement linéaire","accroche":"Une droite pour prévoir les ventes du mois prochain.","intro":"Si le nuage est allongé, une droite peut le résumer.","objectifs":["calculer une droite d'ajustement","faire une prévision","juger sa fiabilité"],"parties":[{"t":"La droite","html":"<div class='def'><b>Formule</b>La <strong>droite d'ajustement</strong> s'écrit <strong>y − ȳ = a(x − x̄)</strong>, avec a = cov(x ; y) / V(x).</div>"},{"t":"Prévoir","verrou":true},{"t":"Fiabilité","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle A","m":"maths","rang":14,"apc":{"module":"Mathématiques de Terminale A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations et interpréter des résultats","situation":"La même vendeuse veut estimer ses ventes pour un prix différent.","tache":"Explique comment l'estimer."},"verrou":true,"nq":4,"labo":true});
VRT_L("tle-a-maths-r15",{"duree":15,"titre":"Les dérivées usuelles","accroche":"Un tableau à connaître par cœur.","intro":"Les dérivées usuelles permettent d'étudier la variation de nombreuses fonctions.","objectifs":["utiliser le tableau","dériver une somme","dériver un produit par une constante"],"parties":[{"t":"Tableau","html":"<div class='def'><b>Dérivées usuelles</b>(xⁿ)' = n xⁿ⁻¹ ; (1/x)' = −1/x² ; (√x)' = 1/(2√x).</div>"},{"t":"Opérations","verrou":true},{"t":"Exemple","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle A","m":"maths","rang":15,"apc":{"module":"Mathématiques de Terminale A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations et interpréter des résultats","situation":"Le chiffre d'affaires d'une boutique de Limbé est modélisé par R(x) = 3x² + 2x.","tache":"Calcule la dérivée."},"verrou":true,"nq":4,"labo":true});
VRT_L("tle-a-maths-r16",{"duree":15,"titre":"Dérivées des fonctions composées","accroche":"Dériver l'enveloppe, puis l'intérieur.","intro":"Une fonction composée se dérive par une règle simple.","objectifs":["reconnaître une composée","appliquer (uⁿ)'","appliquer (√u)'"],"parties":[{"t":"Formules","html":"<div class='def'><b>Formules</b><strong>(uⁿ)' = n u' uⁿ⁻¹</strong> et <strong>(√u)' = u' / (2√u)</strong>.</div>"},{"t":"Exemple","verrou":true},{"t":"Méthode","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle A","m":"maths","rang":16,"apc":{"module":"Mathématiques de Terminale A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations et interpréter des résultats","situation":"Un coût de transport de Bafoussam suit la loi C(x) = (2x + 1)³.","tache":"Donne C'(x)."},"verrou":true,"nq":4,"labo":true});
VRT_L("tle-a-maths-r17",{"duree":25,"titre":"Intégration : la meilleure quantité à produire","accroche":"Dériver pour décider.","intro":"La dérivée d'un bénéfice indique la quantité la plus avantageuse.","objectifs":["dériver un bénéfice","trouver un maximum","conclure"],"parties":[{"t":"Le problème","html":"<div class='def'><b>Intégration</b>Le <strong>bénéfice maximal</strong> s'obtient en cherchant où la dérivée s'annule en changeant de signe.</div><p>B(x) = −x² + 10x − 16.</p>"},{"t":"Le calcul","verrou":true},{"t":"Conclure","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle A","m":"maths","rang":17,"apc":{"module":"Mathématiques de Terminale A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations et interpréter des résultats","situation":"Un atelier de couture de Ngaoundéré modélise son bénéfice par B(x) = −x² + 10x − 16.","tache":"Trouve la production la plus rentable."},"verrou":true,"nq":4,"labo":true});
VRT_L("tle-a-maths-r18",{"duree":20,"titre":"Dérivée et sens de variation","accroche":"Le signe de la dérivée indique où ça monte, où ça descend.","intro":"La dérivée fournit les variations complètes d'une fonction.","objectifs":["étudier le signe de f'","dresser un tableau","trouver les extremums"],"parties":[{"t":"Le théorème","html":"<div class='def'><b>Théorème</b>Sur un intervalle : f' > 0 ⇒ f <strong>croissante</strong> ; f' < 0 ⇒ f <strong>décroissante</strong>.</div>"},{"t":"Exemple","html":"<p>f(x) = x³ − 3x : f'(x) = 3x² − 3, nul en ±1.</p><p>f(−1) = 2 est un maximum local, f(1) = −2, un minimum local.</p>","labo":{"type":"courbe","fn":"x3","xmin":-2,"xmax":2,"ymin":-5,"ymax":5,"x0":-1}},{"t":"Tableau","html":"<p>On présente les zéros de f', le signe, puis les variations.</p>","retenir":"Un extremum : f' s'annule en changeant de signe."},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Question de cours.</strong> f' &gt; 0 indique :</p><ol type='a'><li>décroissante</li><li>croissante</li><li>constante</li></ol><details><summary>Voir la réponse</summary><p><strong>croissante</strong>. Théorème.</p></details><p><strong>Exercice.</strong></p><p>Sens de x² sur [0 ; +∞[.</p><details><summary>Voir la réponse</summary><p>(Réponse : croissante.)</p></details><h3>Partie B : évaluation des compétences</h3><p><strong>Situation.</strong> On étudie f(x) = x³ − 3x² − 9x + 5 sur [−3 ; 5].</p><p><strong>Tâche 1.</strong> Calcule f'(x) et factorise-la.</p><p><strong>Tâche 2.</strong> Dresse le tableau de variation de f.</p><details><summary>Voir une réponse attendue</summary><p>f'(x) = 3x² − 6x − 9 = 3(x + 1)(x − 3). f est croissante sur [−3 ; −1], décroissante sur [−1 ; 3], croissante sur [3 ; 5]. f(−3) = −22 ; f(−1) = 10 ; f(3) = −22 ; f(5) = 10.</p></details></div>","retenir":"Savoir-être mobilisé : Esprit critique face aux résultats."}],"revision":["f' > 0 : croissante.","f' < 0 : décroissante.","Extremums."],"exo":"<p>Sens de x² sur [0 ; +∞[. <em>(Réponse : croissante.)</em></p>","quiz":[{"q":"f' > 0 indique :","r":["décroissante","croissante","constante"],"b":1,"e":"Théorème."},{"q":"f' s'annule et change de signe :","r":["extremum","asymptote","racine de f"],"b":0,"e":"Maximum ou minimum."},{"q":"f(x) = x³ − 3x : f'(1) vaut :","r":["3","−3","0"],"b":2,"e":"3 − 3."},{"q":"Le tableau présente :","r":["la couleur","les variations","les noms"],"b":1,"e":"Signe et sens."}],"c":"Tle A","m":"maths","rang":18,"apc":{"module":"Mathématiques de Terminale A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations et interpréter des résultats","situation":"Le niveau d'une retenue d'eau à Mbalmayo est modélisé par une fonction dérivable.","tache":"Dis comment savoir s'il monte ou s'il baisse."},"gratuit":true});
VRT_L("tle-a-maths-r19",{"duree":15,"titre":"Centre et axe de symétrie d'une courbe","accroche":"Dessiner la moitié, et la symétrie fait le reste.","intro":"Une symétrie permet d'étudier une fonction sur un intervalle réduit.","objectifs":["prouver un axe de symétrie","prouver un centre","réduire l'étude"],"parties":[{"t":"Axe","html":"<div class='def'><b>Propriété</b>La droite x = a est <strong>axe de symétrie</strong> si f(2a − x) = f(x).</div>"},{"t":"Centre","verrou":true},{"t":"Réduire l'étude","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle A","m":"maths","rang":19,"apc":{"module":"Mathématiques de Terminale A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations et interpréter des résultats","situation":"Un motif décoratif de façade à Foumban est symétrique.","tache":"Dis comment simplifier son tracé à partir d'une fonction paire."},"verrou":true,"nq":4,"labo":true});
VRT_L("tle-a-maths-r20",{"duree":15,"titre":"Les asymptotes","accroche":"La courbe s'approche, sans jamais vraiment toucher.","intro":"Une asymptote est une droite dont la courbe se rapproche à l'infini.","objectifs":["trouver une asymptote verticale","trouver une asymptote horizontale","trouver une asymptote oblique"],"parties":[{"t":"Trois cas","html":"<div class='def'><b>Asymptotes</b>Verticale x = a si f tend vers ±∞ en a. Horizontale y = b si f tend vers b en ±∞. Oblique y = ax + b si f(x) − (ax + b) tend vers 0.</div>"},{"t":"Exemple","verrou":true},{"t":"Tracé","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle A","m":"maths","rang":20,"apc":{"module":"Mathématiques de Terminale A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations et interpréter des résultats","situation":"Le coût moyen d'un livre tend vers 500 F quand le tirage augmente.","tache":"Traduis ce fait graphiquement."},"verrou":true,"nq":4,"labo":true});
VRT_L("tle-a-maths-r21",{"duree":15,"titre":"Primitives des fonctions usuelles","accroche":"Retrouver une fonction à partir de sa dérivée.","intro":"Primitive et dérivée sont des opérations inverses.","objectifs":["utiliser le tableau","trouver une primitive","ajouter une constante"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>F est une <strong>primitive</strong> de f si F' = f. Les primitives de f sont les fonctions F + k.</div>"},{"t":"Tableau","verrou":true},{"t":"Exemple","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle A","m":"maths","rang":21,"apc":{"module":"Mathématiques de Terminale A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations et interpréter des résultats","situation":"Le coût marginal d'un atelier de Yaoundé vaut 2x + 3 (milliers de francs).","tache":"Donne le coût total, à une constante près."},"verrou":true,"nq":4,"labo":true});
VRT_L("tle-a-maths-r22",{"duree":25,"titre":"Intégration : du coût marginal au coût total","accroche":"Remonter d'un coût unitaire au coût global.","intro":"Une entreprise connaît son coût marginal et ses frais fixes. Elle veut retrouver son coût total.","objectifs":["chercher une primitive","utiliser une condition","conclure"],"parties":[{"t":"Le problème","html":"<div class='def'><b>Rappel</b>Le coût total est une <strong>primitive du coût marginal</strong>. La constante correspond aux frais fixes.</div>"},{"t":"Le calcul","verrou":true},{"t":"Conclure","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle A","m":"maths","rang":22,"apc":{"module":"Mathématiques de Terminale A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations et interpréter des résultats","situation":"Un artisan de Bafang connaît son coût marginal 2x + 3 et ses frais fixes de 4 000 F.","tache":"Écris son coût total."},"verrou":true,"nq":4,"labo":true});
VRT_L("tle-a-maths-r23",{"duree":20,"titre":"Le logarithme népérien : définition et propriétés","accroche":"Une fonction qui transforme les produits en sommes.","intro":"Le logarithme népérien simplifie les calculs de croissance et d'intérêts.","objectifs":["connaître le domaine de ln","utiliser les propriétés","simplifier une expression"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>La fonction <strong>ln</strong> est définie sur ]0 ; +∞[. On a ln 1 = 0 et ln e = 1.</div>"},{"t":"Propriétés","verrou":true},{"t":"Simplifier","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle A","m":"maths","rang":23,"apc":{"module":"Mathématiques de Terminale A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations et interpréter des résultats","situation":"Une banque de Yaoundé annonce des intérêts composés et utilise le logarithme pour calculer les durées de placement.","tache":"Écris ln(1,1²) en utilisant les propriétés."},"verrou":true,"nq":4,"labo":true});
VRT_L("tle-a-maths-r24",{"duree":20,"titre":"Équations avec ln comme inconnue auxiliaire","accroche":"Poser X = ln x, et l'équation devient familière.","intro":"Une équation contenant ln x peut se ramener à une équation du second degré.","objectifs":["trouver les conditions","poser X = ln x","revenir à x"],"parties":[{"t":"Méthode","html":"<div class='def'><b>Méthode</b>Après avoir fixé le domaine x > 0, on pose <strong>X = ln x</strong>, puis on résout en X.</div>"},{"t":"Exemple","verrou":true},{"t":"Inéquations","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle A","m":"maths","rang":24,"apc":{"module":"Mathématiques de Terminale A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations et interpréter des résultats","situation":"Une coopérative de Dschang estime ses ventes par N = (ln t)² − 3 ln t + 2, où t est le nombre de jours de campagne publicitaire ; elle cherche les jours où N = 0.","tache":"Résous l'équation en présentant les étapes."},"verrou":true,"nq":4,"labo":true});
VRT_L("tle-a-maths-r25",{"duree":15,"titre":"Limites usuelles du logarithme","accroche":"Le logarithme grandit, mais très lentement.","intro":"Trois limites suffisent pour étudier les fonctions contenant ln.","objectifs":["connaître les limites","lever une indétermination","interpréter"],"parties":[{"t":"Limites","html":"<div class='def'><b>Limites</b>ln x → +∞ en +∞ ; ln x → −∞ en 0⁺ ; <strong>ln x / x → 0</strong> en +∞.</div>"},{"t":"Autre limite","verrou":true},{"t":"Interprétation","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle A","m":"maths","rang":25,"apc":{"module":"Mathématiques de Terminale A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations et interpréter des résultats","situation":"La rentabilité d'une plantation d'Ebolowa croît comme ln x, pour x hectares, tandis que les charges croissent comme x.","tache":"Compare à long terme."},"verrou":true,"nq":4,"labo":true});
VRT_L("tle-a-maths-r26",{"duree":20,"titre":"Dérivée et primitives avec ln","accroche":"u'/u : la forme à reconnaître.","intro":"La fonction ln donne la dérivée de ln u et une primitive de u'/u.","objectifs":["dériver ln u","reconnaître u'/u","calculer une primitive"],"parties":[{"t":"Dérivée","html":"<div class='def'><b>Formule</b>Si u > 0 : <strong>(ln u)' = u' / u</strong>.</div>"},{"t":"Primitive","verrou":true},{"t":"Application","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle A","m":"maths","rang":26,"apc":{"module":"Mathématiques de Terminale A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations et interpréter des résultats","situation":"Le rendement d'une ferme de Bafia, en tonnes, est modélisé par R(x) = ln(2x + 1), x étant la dose d'engrais en sacs.","tache":"Calcule R'(x) et interprète son signe."},"verrou":true,"nq":4,"labo":true});
VRT_L("tle-a-maths-r27",{"duree":20,"titre":"La fonction exponentielle : définition et propriétés","accroche":"La croissance rapide a son écriture : eˣ.","intro":"La fonction exponentielle est la réciproque de ln.","objectifs":["définir eˣ","utiliser ses propriétés","simplifier"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>La fonction <strong>exponentielle</strong> est définie sur ℝ et strictement positive. e⁰ = 1 et e¹ = e ≈ 2,718.</div>"},{"t":"Propriétés","verrou":true},{"t":"Lien avec ln","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle A","m":"maths","rang":27,"apc":{"module":"Mathématiques de Terminale A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations et interpréter des résultats","situation":"La population d'une ville modélisée à Douala est de la forme 1 000 e^(0,03t).","tache":"Calcule e⁰ et interprète."},"verrou":true,"nq":4,"labo":true});
VRT_L("tle-a-maths-r28",{"duree":15,"titre":"Équations ln x = y et eˣ = y","accroche":"Deux équations, résolues par la fonction réciproque.","intro":"ln et exp sont réciproques : chacune permet de résoudre une équation contenant l'autre.","objectifs":["résoudre ln x = y","résoudre eˣ = y","vérifier les conditions"],"parties":[{"t":"Les équivalences","html":"<div class='def'><b>Propriété</b><strong>ln x = y ⇔ x = eʸ</strong>. Pour y > 0, <strong>eˣ = y ⇔ x = ln y</strong>.</div>"},{"t":"Exemples","verrou":true},{"t":"Cas impossible","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle A","m":"maths","rang":28,"apc":{"module":"Mathématiques de Terminale A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations et interpréter des résultats","situation":"Un capital de Kumba est multiplié par eˣ, et on veut qu'il soit multiplié par 5.","tache":"Trouve x."},"verrou":true,"nq":4,"labo":true});
VRT_L("tle-a-maths-r29",{"duree":20,"titre":"Équations avec eˣ comme inconnue auxiliaire","accroche":"Poser X = eˣ, sans oublier X > 0.","intro":"Les équations contenant e^(2x) et eˣ se ramènent au second degré.","objectifs":["poser X = eˣ","écarter les valeurs impossibles","résoudre"],"parties":[{"t":"Méthode","html":"<div class='def'><b>Méthode</b>On pose <strong>X = eˣ</strong>, avec X > 0, et on remarque que e^(2x) = X².</div>"},{"t":"Exemple","verrou":true},{"t":"Valeur à écarter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle A","m":"maths","rang":29,"apc":{"module":"Mathématiques de Terminale A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations et interpréter des résultats","situation":"La production d'une usine de Garoua vérifie e^(2x) − 3eˣ + 2 = 0 au moment où elle s'équilibre, x en mois.","tache":"Résous l'équation."},"verrou":true,"nq":4,"labo":true});
VRT_L("tle-a-maths-r30",{"duree":20,"titre":"La fonction x ↦ aˣ : définition et propriétés","accroche":"Un taux de croissance annuel s'écrit aˣ.","intro":"Les fonctions de base a généralisent l'exponentielle.","objectifs":["définir aˣ","utiliser les propriétés","relier au logarithme"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Pour a > 0, <strong>aˣ = e^(x ln a)</strong>.</div>"},{"t":"Propriétés","verrou":true},{"t":"Logarithme","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle A","m":"maths","rang":30,"apc":{"module":"Mathématiques de Terminale A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations et interpréter des résultats","situation":"Une épargne de Bafoussam augmente de 10 % chaque année.","tache":"Écris le coefficient après x années."},"verrou":true,"nq":4,"labo":true});
VRT_L("tle-a-maths-r31",{"duree":15,"titre":"Équations avec log x et 10ˣ","accroche":"Le logarithme décimal résout les équations de puissance.","intro":"Le logarithme décimal et les puissances de 10 sont réciproques.","objectifs":["résoudre log x = y","résoudre 10ˣ = y","résoudre aˣ = y"],"parties":[{"t":"Équivalences","html":"<div class='def'><b>Propriété</b><strong>log x = y ⇔ x = 10ʸ</strong>. Pour y > 0, <strong>10ˣ = y ⇔ x = log y</strong>.</div>"},{"t":"Cas général","verrou":true},{"t":"Exemple","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle A","m":"maths","rang":31,"apc":{"module":"Mathématiques de Terminale A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations et interpréter des résultats","situation":"Une somme placée à 10 % à Yaoundé doit doubler.","tache":"Écris x à l'aide des logarithmes."},"verrou":true,"nq":4,"labo":true});
VRT_L("tle-a-maths-r32",{"duree":20,"titre":"Équations avec aˣ comme inconnue auxiliaire","accroche":"Poser X = 2ˣ, comme pour eˣ.","intro":"La méthode de l'inconnue auxiliaire s'applique à toutes les bases.","objectifs":["poser X = aˣ","résoudre","revenir à x"],"parties":[{"t":"Méthode","html":"<div class='def'><b>Méthode</b>On pose <strong>X = aˣ</strong>, avec X > 0, et a^(2x) = X².</div>"},{"t":"Exemple","verrou":true},{"t":"Rejet","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle A","m":"maths","rang":32,"apc":{"module":"Mathématiques de Terminale A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations et interpréter des résultats","situation":"Un pêcheur de Kribi modélise le nombre de bancs de poissons repérés par 4ˣ − 3 × 2ˣ + 2 = 0, x en heures après le départ, aux instants où son sonar ne détecte plus rien.","tache":"Résous l'équation."},"verrou":true,"nq":4,"labo":true});
VRT_L("tle-a-maths-r33",{"duree":20,"titre":"Exponentielle : dérivées et primitives","accroche":"La dérivée de eᵘ, c'est u' eᵘ.","intro":"Les dérivées et les primitives de l'exponentielle reviennent souvent dans les études de fonctions.","objectifs":["dériver e^u","reconnaître u' e^u","calculer une primitive"],"parties":[{"t":"Formules","html":"<div class='def'><b>Formule</b><strong>(eᵘ)' = u' eᵘ</strong>. Une primitive de u' eᵘ est <strong>eᵘ</strong>.</div>"},{"t":"Exemples","verrou":true},{"t":"Application","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle A","m":"maths","rang":33,"apc":{"module":"Mathématiques de Terminale A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations et interpréter des résultats","situation":"Le nombre d'abonnés d'une radio de Bertoua croît selon e^(2t).","tache":"Calcule la vitesse de croissance."},"verrou":true,"nq":4,"labo":true});
VRT_L("tle-a-maths-r34",{"duree":15,"titre":"Limites usuelles de l'exponentielle","accroche":"L'exponentielle l'emporte sur toutes les puissances.","intro":"Ces limites sont essentielles pour lever les indéterminations.","objectifs":["connaître les limites","comparer","appliquer"],"parties":[{"t":"Limites","html":"<div class='def'><b>Limites</b>eˣ → +∞ en +∞ ; eˣ → 0 en −∞ ; <strong>eˣ / x → +∞</strong> en +∞ ; <strong>x eˣ → 0</strong> en −∞.</div>"},{"t":"Exemple","verrou":true},{"t":"Interprétation","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle A","m":"maths","rang":34,"apc":{"module":"Mathématiques de Terminale A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations et interpréter des résultats","situation":"On compare à long terme une épargne exponentielle à une épargne qui augmente d'un montant fixe chaque mois à Dschang.","tache":"Dis laquelle finit par être la plus grande."},"verrou":true,"nq":4,"labo":true});
VRT_L("tle-a-maths-r35",{"duree":15,"titre":"Fonctions aˣ : dérivées et primitives","accroche":"ln a apparaît à chaque dérivation.","intro":"La dérivée d'une fonction de base a contient ln a.","objectifs":["dériver aˣ","trouver une primitive","étudier le sens de variation"],"parties":[{"t":"Formules","html":"<div class='def'><b>Formules</b><strong>(aˣ)' = aˣ ln a</strong>. Une primitive de aˣ est <strong>aˣ / ln a</strong>, pour a ≠ 1.</div>"},{"t":"Sens de variation","verrou":true},{"t":"Exemple","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle A","m":"maths","rang":35,"apc":{"module":"Mathématiques de Terminale A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations et interpréter des résultats","situation":"Une coopérative de Mbouda voit ses ventes multipliées par 2 chaque année.","tache":"Dis si les ventes augmentent ou diminuent."},"verrou":true,"nq":4,"labo":true});
VRT_L("tle-a-maths-r36",{"duree":15,"titre":"Limites des fonctions aˣ","accroche":"Tout dépend de la position de a par rapport à 1.","intro":"Le comportement en l'infini de aˣ dépend de la valeur de a.","objectifs":["déterminer les limites","distinguer les cas","interpréter"],"parties":[{"t":"Cas a > 1","html":"<div class='def'><b>Limites</b>Si a > 1 : aˣ → +∞ en +∞ et aˣ → 0 en −∞. Si 0 < a < 1 : aˣ → 0 en +∞ et aˣ → +∞ en −∞.</div>"},{"t":"Exemple","verrou":true},{"t":"Interpréter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle A","m":"maths","rang":36,"apc":{"module":"Mathématiques de Terminale A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations et interpréter des résultats","situation":"Un médicament est éliminé de moitié toutes les 6 heures.","tache":"Dis ce que devient sa quantité à long terme."},"verrou":true,"nq":4,"labo":true});
VRT_L("tle-a-maths-r37",{"duree":25,"titre":"Intégration : le doublement d'une population","accroche":"En combien de temps une ville double-t-elle ?","intro":"La croissance d'une population est modélisée par une fonction exponentielle.","objectifs":["modéliser","résoudre avec ln","interpréter"],"parties":[{"t":"Le modèle","html":"<div class='def'><b>Modèle</b>Un taux annuel continu r donne <strong>P(t) = P₀ e^(rt)</strong>.</div>"},{"t":"Le calcul","verrou":true},{"t":"Interpréter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle A","m":"maths","rang":37,"apc":{"module":"Mathématiques de Terminale A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations et interpréter des résultats","situation":"Le comité de développement d'une commune de l'Ouest veut savoir quand la population doublera avec un taux de 3 % par an.","tache":"Calcule le temps de doublement."},"verrou":true,"nq":4,"labo":true});
VRT_L("tle-a-maths-r38",{"duree":15,"titre":"Le vocabulaire des événements","accroche":"Nommer avant de calculer.","intro":"Le vocabulaire des probabilités permet de décrire précisément une expérience aléatoire.","objectifs":["définir univers et événement","décrire un événement","utiliser le contraire"],"parties":[{"t":"Vocabulaire","html":"<div class='def'><b>Définitions</b>L'<strong>univers</strong> est l'ensemble des issues possibles. Un <strong>événement</strong> est un ensemble d'issues.</div>"},{"t":"Opérations","html":"<ul><li>A et B : A ∩ B.</li><li>A ou B : A ∪ B.</li><li>Contraire de A : Ā.</li></ul>","labo":{"type":"trier","invite":"Choisis une notion.","items":[["Univers","toutes les issues."],["Événement","une partie de l'univers."],["Contraire","ce qui n'est pas dans l'événement."]]}},{"t":"Exemple","html":"<p>Dé : A = {2, 4, 6}, contraire Ā = {1, 3, 5}.</p>","retenir":"Décrire l'univers avant de compter."},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Question de cours.</strong> L'univers contient :</p><ol type='a'><li>une issue</li><li>toutes les issues</li><li>aucune issue</li></ol><details><summary>Voir la réponse</summary><p><strong>toutes les issues</strong>. Définition.</p></details><p><strong>Exercice.</strong></p><p>Donne l'univers d'un lancer de pièce.</p><details><summary>Voir la réponse</summary><p>(Réponse : {pile ; face}.)</p></details><h3>Partie B : évaluation des compétences</h3><p><strong>Situation.</strong> À la kermesse d'un lycée de Kribi, on lance un dé équilibré à six faces. A : « le résultat est pair » ; B : « le résultat est au moins 4 » ; C : « le résultat est 1 ».</p><p><strong>Tâche 1.</strong> Écris A ∩ B, A ∪ B et l'événement contraire de A.</p><p><strong>Tâche 2.</strong> A et C sont-ils incompatibles ? Justifie.</p><details><summary>Voir une réponse attendue</summary><p>A ∩ B = {4 ; 6} ; A ∪ B = {2 ; 4 ; 5 ; 6} ; Ā = {1 ; 3 ; 5}. A ∩ C = ∅ : A et C sont incompatibles.</p></details></div>","retenir":"Savoir-être mobilisé : Rigueur dans la rédaction."}],"revision":["Univers.","Événement.","Contraire."],"exo":"<p>Donne l'univers d'un lancer de pièce. <em>(Réponse : {pile ; face}.)</em></p>","quiz":[{"q":"L'univers contient :","r":["une issue","toutes les issues","aucune issue"],"b":1,"e":"Définition."},{"q":"A ∩ B signifie :","r":["A et B","A ou B","ni A ni B"],"b":0,"e":"Intersection."},{"q":"Le contraire de {2, 4, 6} sur un dé :","r":["{2, 4}","{6}","{1, 3, 5}"],"b":2,"e":"Les autres issues."},{"q":"Un événement est :","r":["un nombre","un ensemble d'issues","un graphique"],"b":1,"e":"Définition."}],"c":"Tle A","m":"maths","rang":38,"apc":{"module":"Mathématiques de Terminale A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations et interpréter des résultats","situation":"Une radio de Douala organise un tirage au sort entre six auditeurs numérotés.","tache":"Décris l'événement « un numéro pair sort »."},"gratuit":true});
