VRT_L("tle-a-maths-r41",{"duree":25,"titre":"Étude des fonctions rationnelles","accroche":"Une valeur interdite, deux branches.","intro":"Les fonctions rationnelles comportent des valeurs interdites et des asymptotes.","objectifs":["trouver le domaine","dériver un quotient","déterminer les asymptotes"],"parties":[{"t":"Domaine","html":"<div class='def'><b>Définition</b>Une <strong>fonction rationnelle</strong> est un quotient de polynômes. Elle n'existe pas là où le dénominateur s'annule.</div>"},{"t":"Dérivée","verrou":true},{"t":"Asymptotes","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle A","m":"maths","rang":41,"apc":{"module":"Mathématiques de Terminale A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations et interpréter des résultats","situation":"Un coût moyen à Limbé s'écrit (x + 1)/(x − 1).","tache":"Détermine le comportement à long terme."},"verrou":true,"nq":4,"labo":true});
